-- PG REL_18_0 oracle; deterministic independent SQL inputs.
WITH inputs(x) AS (VALUES ('1'),('0.9'),('1.1'),('2'),('10'),('0.00001'),('1e1000'),('1e-1000'),('1.00000000000000000000000000001'),('0.99999999999999999999999999999') UNION ALL SELECT ((i*7919%100003+1)::numeric/1000)::text FROM generate_series(1,200) i), results AS (SELECT 'ln' AS op,x,ln(x::numeric) AS y FROM inputs UNION ALL SELECT 'exp',x,exp(x::numeric) FROM inputs WHERE abs(x::numeric)<100 UNION ALL SELECT 'log',x,log(3::numeric,x::numeric) FROM inputs) SELECT op,x,y::text,scale(y),encode(numeric_send(y),'hex') FROM results;
WITH inputs(x) AS (VALUES ('1e-16383'),('1e16383'),('0.90000000000000000000001'),('1.09999999999999999999999'),('0.99999999999999999999999999999999999999999999999999')), results AS (SELECT 'ln' op,x,ln(x::numeric) y FROM inputs UNION ALL SELECT 'log',x,log(3::numeric,x::numeric) FROM inputs UNION ALL SELECT 'exp',x,exp(x::numeric) FROM (VALUES ('5999'),('-5999'),('-6000'),('6000e-10'),('0.00'),('-0.0001'),('1e-16383')) v(x)) SELECT op,x,y::text,scale(y),encode(numeric_send(y),'hex') FROM results;
WITH inputs(base,x) AS (VALUES ('1.000000000000000000000000000001','2'),('0.999999999999999999999999999999','2'),('0.00001','1e1000'),('1e1000','0.00001'),('2','1.000000000000000000000000000001')), results AS (SELECT 'log:'||base op,x,log(base::numeric,x::numeric) y FROM inputs) SELECT op,x,y::text,scale(y),encode(numeric_send(y),'hex') FROM results;
